B.bqM=new A.dU("This PDF is a scan with no text in it. Take a screenshot of it and check that.","\u092f\u0947 PDF \u0938\u094d\u0915\u0948\u0928 \u0939\u0948, \u0907\u0938\u092e\u0947\u0902 \u091f\u0947\u0915\u094d\u0938\u094d\u091f \u0928\u0939\u0940\u0902 \u0939\u0948\u0964 \u0907\u0938\u0915\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0932\u0947\u0915\u0930 \u091c\u093e\u0902\u091a\u0947\u0902\u0964","\u0939\u0940 PDF \u0938\u094d\u0915\u0945\u0928 \u0906\u0939\u0947, \u0924\u093f\u091a\u094d\u092f\u093e\u0924 \u092e\u091c\u0915\u0942\u0930 \u0928\u093e\u0939\u0940. \u0924\u093f\u091a\u093e \u0938\u094d\u0915\u094d\u0930\u0940\u0928\u0936\u0949\u091f \u0918\u0947\u090a\u0928 \u0924\u092a\u093e\u0938\u093e.")
B.bqN=new A.dU("Call 1930, the cyber fraud helpline","1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902, \u0938\u093e\u0907\u092c\u0930 \u092b\u094d\u0930\u0949\u0921 \u0939\u0947\u0932\u094d\u092a\u0932\u093e\u0907\u0928","1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e, \u0938\u093e\u092f\u092c\u0930 \u092b\u0938\u0935\u0923\u0942\u0915 \u0939\u0947\u0932\u094d\u092a\u0932\u093e\u0907\u0928")
B.bqO=new A.dU("No known red flags, still verify","\u0915\u094b\u0908 \u091c\u093e\u0928\u093e-\u092a\u0939\u091a\u093e\u0928\u093e \u0916\u0924\u0930\u093e \u0928\u0939\u0940\u0902 \u0926\u093f\u0916\u093e, \u092b\u093f\u0930 \u092d\u0940 \u091c\u093e\u0902\u091a \u0932\u0947\u0902","\u0913\u0933\u0916\u0940\u091a\u093e \u0927\u094b\u0915\u093e \u0926\u093f\u0938\u0932\u093e \u0928\u093e\u0939\u0940, \u0924\u0930\u0940\u0939\u0940 \u0916\u093e\u0924\u094d\u0930\u0940 \u0915\u0930\u093e")
B.bqP=new A.dU("Phone numbers, UPI IDs and names from the message are hidden on the card.","\u092e\u0948\u0938\u0947\u091c \u0915\u0947 \u092b\u093c\u094b\u0928 \u0928\u0902\u092c\u0930, UPI ID \u0914\u0930 \u0928\u093e\u092e \u0915\u093e\u0930\u094d\u0921 \u092a\u0930 \u091b\u0941\u092a\u093e \u0926\u093f\u090f \u0917\u090f \u0939\u0948\u0902\u0964","\u092e\u0947\u0938\u0947\u091c\u092e\u0927\u0932\u0947 \u092b\u094b\u0928 \u0928\u0902\u092c\u0930, UPI ID \u0906\u0923\u093f \u0928\u093e\u0935\u0902 \u0915\u093e\u0930\u094d\u0921\u0935\u0930 \u0932\u092a\u0935\u0932\u0940 \u0906\u0939\u0947\u0924.")
B.bqQ=new A.dU("Lost money? Call 1930 or report on cybercrime.gov.in","\u092a\u0948\u0938\u0947 \u0917\u090f? 1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902 \u092f\u093e cybercrime.gov.in \u092a\u0930 \u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0947\u0902","\u092a\u0948\u0938\u0947 \u0917\u0947\u0932\u0947? 1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e \u0915\u093f\u0902\u0935\u093e cybercrime.gov.in \u0935\u0930 \u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0930\u093e")
B.bqR=new A.dU("Report it","\u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0947\u0902","\u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0930\u093e")
B.bqS=new A.dU("From the message, with numbers and names hidden","\u092e\u0948\u0938\u0947\u091c \u0938\u0947, \u0928\u0902\u092c\u0930 \u0914\u0930 \u0928\u093e\u092e \u091b\u0941\u092a\u093e\u0915\u0930","\u092e\u0947\u0938\u0947\u091c\u092e\u0927\u0942\u0928, \u0928\u0902\u092c\u0930 \u0906\u0923\u093f \u0928\u093e\u0935\u0902 \u0932\u092a\u0935\u0942\u0928")
