B.bqV=new A.dU("Nox reads it in this browser. Nothing is uploaded.","Nox \u0907\u0938\u0947 \u0907\u0938\u0940 \u092c\u094d\u0930\u093e\u0909\u091c\u093c\u0930 \u092e\u0947\u0902 \u092a\u0922\u093c\u0924\u093e \u0939\u0948\u0964 \u0915\u0941\u091b \u092d\u0940 \u0905\u092a\u0932\u094b\u0921 \u0928\u0939\u0940\u0902 \u0939\u094b\u0924\u093e\u0964","Nox \u0939\u0947 \u092f\u093e\u091a \u092c\u094d\u0930\u093e\u0909\u091d\u0930\u092e\u0927\u094d\u092f\u0947 \u0935\u093e\u091a\u0924\u094b. \u0915\u093e\u0939\u0940\u0939\u0940 \u0905\u092a\u0932\u094b\u0921 \u0939\u094b\u0924 \u0928\u093e\u0939\u0940.")
B.bqW=new A.dU("Checked on my phone with NO SUS \xb7 nosus.foo","\u092e\u0947\u0930\u0947 \u092b\u093c\u094b\u0928 \u092a\u0930 NO SUS \u0938\u0947 \u091c\u093e\u0902\u091a\u093e \xb7 nosus.foo","\u092e\u093e\u091d\u094d\u092f\u093e \u092b\u094b\u0928\u0935\u0930 NO SUS \u0928\u0947 \u0924\u092a\u093e\u0938\u0932\u0902 \xb7 nosus.foo")
B.bqX=new A.dU("Got a message that feels off? Nox reads it.","\u0915\u094b\u0908 \u092e\u0948\u0938\u0947\u091c \u0905\u091c\u0940\u092c \u0932\u0917\u093e? Nox \u092a\u0922\u093c\u0915\u0930 \u092c\u0924\u093e\u090f\u0917\u093e\u0964","\u090f\u0916\u093e\u0926\u093e \u092e\u0947\u0938\u0947\u091c \u0935\u093f\u091a\u093f\u0924\u094d\u0930 \u0935\u093e\u091f\u0932\u093e? Nox \u0935\u093e\u091a\u0942\u0928 \u0938\u093e\u0902\u0917\u0947\u0932.")
B.bqY=new A.dU("Call 1930 now and tell your bank. Reporting in the first hours gives the bank the best chance to hold the money.","\u0905\u092d\u0940 1930 \u092a\u0930 \u0915\u0949\u0932 \u0915\u0930\u0947\u0902 \u0914\u0930 \u092c\u0948\u0902\u0915 \u0915\u094b \u092c\u0924\u093e\u090f\u0902\u0964 \u092a\u0939\u0932\u0947 \u0915\u0941\u091b \u0918\u0902\u091f\u094b\u0902 \u092e\u0947\u0902 \u0936\u093f\u0915\u093e\u092f\u0924 \u0915\u0930\u0928\u0947 \u0938\u0947 \u092c\u0948\u0902\u0915 \u0915\u0947 \u092a\u093e\u0938 \u092a\u0948\u0938\u093e \u0930\u094b\u0915\u0928\u0947 \u0915\u093e \u0938\u092c\u0938\u0947 \u0905\u091a\u094d\u091b\u093e \u092e\u094c\u0915\u093e \u0939\u094b\u0924\u093e \u0939\u0948\u0964","\u0906\u0924\u094d\u0924\u093e\u091a 1930 \u0935\u0930 \u0915\u0949\u0932 \u0915\u0930\u093e \u0906\u0923\u093f \u092c\u0901\u0915\u0947\u0932\u093e \u0915\u0933\u0935\u093e. \u092a\u0939\u093f\u0932\u094d\u092f\u093e \u0915\u093e\u0939\u0940 \u0924\u093e\u0938\u093e\u0902\u0924 \u0924\u0915\u094d\u0930\u093e\u0930 \u0915\u0947\u0932\u094d\u092f\u093e\u0938 \u092c\u0901\u0915\u0947\u0932\u093e \u092a\u0948\u0938\u0947 \u0925\u093e\u0902\u092c\u0935\u0923\u094d\u092f\u093e\u091a\u0940 \u0938\u0930\u094d\u0935\u093e\u0924 \u091a\u093e\u0902\u0917\u0932\u0940 \u0938\u0902\u0927\u0940 \u092e\u093f\u0933\u0924\u0947.")
